(function(){
  'use strict';
  const K={sites:'traficcagent-mvd-manual-sites-v1',links:'traficcagent-mvd-links-v1',content:'traficcagent-mvd-content-v1',campaigns:'traficcagent-mvd-campaigns-v1',events:'traficcagent-mvd-events-v1'};
  const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))||d}catch(_){return d}},write=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
  let sites=read(K.sites,[['Casa que Pensa','Casa inteligente','Ana','Publicado']]).map((x,i)=>({id:x.id||'s'+i,nome:x.nome||x[0],nicho:x.nicho||x[1],responsavel:x.responsavel||x[2],status:x.status||x[3]}));
  let links=read(K.links,[]), content=read(K.content,[]), campaigns=read(K.campaigns,[]), events=read(K.events,[]);
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
  const save=()=>{write(K.sites,sites);write(K.links,links);write(K.content,content);write(K.campaigns,campaigns);write(K.events,events)};
  const log=(text)=>{events.unshift({text,time:new Date().toLocaleString('pt-BR')});save()};
  function modal(title,fields,done){const box=document.createElement('div');box.className='modal open';box.innerHTML='<div class="modal-box"><h2>'+esc(title)+'</h2><form class="form-grid">'+fields.map(f=>'<div class="field '+(f.full?'full':'')+'"><label>'+esc(f.label)+'</label><input name="'+esc(f.name)+'" value="'+esc(f.value||'')+'" '+(f.required?'required':'')+'></div>').join('')+'<div class="modal-actions full"><button type="button" class="btn" data-cancel>Cancelar</button><button class="btn primary">Salvar</button></div></form></div>';document.body.appendChild(box);box.querySelector('[data-cancel]').onclick=()=>box.remove();box.querySelector('form').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));done(o);box.remove();renderAll()};}
  function siteEdit(i){const x=sites[i];modal('Editar site',[{name:'nome',label:'Nome',value:x.nome,required:true},{name:'nicho',label:'Nicho',value:x.nicho,required:true},{name:'responsavel',label:'Responsável',value:x.responsavel},{name:'status',label:'Status',value:x.status}],o=>{Object.assign(x,o);log('Site editado: '+x.nome)})}
  function linkEdit(i){const x=links[i];modal('Editar link',[{name:'network',label:'Rede',value:x.network},{name:'product',label:'Produto',value:x.product},{name:'site',label:'Site',value:x.site},{name:'url',label:'URL',value:x.url,required:true}],o=>{Object.assign(x,o);log('Link editado: '+x.product)})}
  function contentEdit(i){const x=content[i];modal('Editar pauta/review',[{name:'title',label:'Título',value:x.title,required:true},{name:'site',label:'Site',value:x.site},{name:'status',label:'Status',value:x.status}],o=>{Object.assign(x,o);log('Pauta/review editada: '+x.title)})}
  function ensureCampaignView(){if(document.querySelector('#campaigns'))return;const n=document.querySelector('.side');n.insertAdjacentHTML('beforeend','<button class="nav" data-view="campaigns">◎ <span>Campanhas e métricas</span></button>');document.querySelector('main').insertAdjacentHTML('beforeend','<section class="view" id="campaigns"><section class="card"><div class="head"><h2>Campanhas e métricas</h2><button class="btn primary" id="newCampaign">+ Nova campanha</button></div><div class="toolbar"><input id="campaignSearch" placeholder="Pesquisar campanha, site ou produto..."></div><div id="campaignList"></div></section></section>');document.querySelector('[data-view="campaigns"]').onclick=()=>{document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id==='campaigns'));document.querySelectorAll('.nav').forEach(v=>v.classList.toggle('active',v.dataset.view==='campaigns'));document.querySelector('#title').textContent='Campanhas e métricas';document.querySelector('#subtitle').textContent='Orçamento, CPC, conversões, ROI e decisão manual.';renderCampaigns()};document.querySelector('#newCampaign').onclick=()=>modal('Nova campanha',[{name:'name',label:'Campanha',required:true},{name:'site',label:'Site'},{name:'product',label:'Produto'},{name:'budget',label:'Orçamento',value:'0'},{name:'clicks',label:'Cliques',value:'0'},{name:'conversions',label:'Conversões',value:'0'},{name:'revenue',label:'Comissão/receita',value:'0'}],o=>{campaigns.push({id:Date.now(),...o,status:'Planejamento'});log('Campanha criada: '+o.name)})}
  function renderCampaigns(){const q=(document.querySelector('#campaignSearch')?.value||'').toLowerCase(),el=document.querySelector('#campaignList');if(!el)return;el.innerHTML=campaigns.filter(x=>(x.name+' '+x.site+' '+x.product).toLowerCase().includes(q)).map((x,i)=>{const budget=+x.budget||0,clicks=+x.clicks||0,conv=+x.conversions||0,revenue=+x.revenue||0,cpc=clicks?budget/clicks:0,roi=budget?(revenue-budget)/budget*100:0;return '<div class="card"><div class="head"><h3>'+esc(x.name)+'</h3><select data-c-status="'+i+'"><option>'+esc(x.status||'Planejamento')+'</option><option>Ativa</option><option>Pausada</option><option>Arquivada</option></select></div><p>'+esc(x.product)+' · '+esc(x.site)+'</p><p>Orçamento: R$ '+budget.toFixed(2)+' · CPC: R$ '+cpc.toFixed(2)+' · Cliques: '+clicks+' · Conversões: '+conv+' · ROI: '+roi.toFixed(1)+'%</p><button class="btn" data-c-edit="'+i+'">Editar métricas</button> <button class="btn" data-c-assoc="'+i+'">Associar fluxo</button></div>'}).join('')||'<p class="muted">Nenhuma campanha cadastrada.</p>';el.querySelectorAll('[data-c-status]').forEach(s=>s.onchange=()=>{campaigns[+s.dataset.cStatus].status=s.value;log('Status de campanha alterado');renderCampaigns()});el.querySelectorAll('[data-c-edit]').forEach(b=>b.onclick=()=>{const x=campaigns[+b.dataset.cEdit];modal('Editar métricas',[{name:'budget',label:'Orçamento',value:x.budget},{name:'clicks',label:'Cliques',value:x.clicks},{name:'conversions',label:'Conversões',value:x.conversions},{name:'revenue',label:'Comissão/receita',value:x.revenue}],o=>Object.assign(x,o))});el.querySelectorAll('[data-c-assoc]').forEach(b=>b.onclick=()=>{const x=campaigns[+b.dataset.cAssoc];modal('Associar fluxo',[{name:'site',label:'Site',value:x.site},{name:'product',label:'Produto',value:x.product},{name:'review',label:'Review',value:x.review}],o=>Object.assign(x,o))})}
  function renderAll(){const t=document.querySelector('#allSites');if(t){t.innerHTML=sites.map((x,i)=>'<tr><td>'+esc(x.nome)+'</td><td>'+esc(x.nicho)+'</td><td>'+esc(x.responsavel)+'</td><td><span class="pill">'+esc(x.status)+'</span></td><td><button class="btn" data-edit-site="'+i+'">Editar</button></td></tr>').join('');t.querySelectorAll('[data-edit-site]').forEach(b=>b.onclick=()=>siteEdit(+b.dataset.editSite))}const l=document.querySelector('#links tbody');if(l){l.innerHTML=links.map((x,i)=>'<tr><td><b>'+esc(x.network)+'</b><small>'+esc(x.product)+'</small></td><td>'+esc(x.site)+'</td><td>—</td><td>Agora</td><td><button class="btn" data-edit-link="'+i+'">Editar</button></td></tr>').join('');l.querySelectorAll('[data-edit-link]').forEach(b=>b.onclick=()=>linkEdit(+b.dataset.editLink))}const c=document.querySelector('#content .queue');if(c){c.querySelectorAll('.card').forEach((el,i)=>{if(content[i])el.insertAdjacentHTML('beforeend','<button class="btn" data-edit-content="'+i+'">Editar</button>')});c.querySelectorAll('[data-edit-content]').forEach(b=>b.onclick=()=>contentEdit(+b.dataset.editContent))}renderCampaigns()}
  function ensureOperationView(){if(document.querySelector('#manualOperation'))return;document.querySelector('.side').insertAdjacentHTML('beforeend','<button class="nav" data-view="manualOperation">⚙ <span>Central de operação</span></button>');document.querySelector('main').insertAdjacentHTML('beforeend','<section class="view" id="manualOperation"><section class="card"><div class="head"><h2>Central de operação</h2><div><button class="btn" id="opBack">← Reabrir etapa</button> <button class="btn primary" id="opNext">Concluir próxima etapa</button></div></div><p class="muted">Fluxo manual persistido com histórico e retorno de etapas.</p><div id="opStages"></div><div id="opHistory"></div></section></section>');const stages=['Produto e nicho','Validação de margem','Link afiliado','Review e indicação','Aprovação humana','Campanha de tráfego','Monitoramento','Decisão'];let op=read('traficcagent-mvd-operation-v1',{step:0,history:[]});const saveOp=()=>write('traficcagent-mvd-operation-v1',op);const renderOp=()=>{document.querySelector('#opStages').innerHTML=stages.map((s,i)=>'<div class="card" style="margin:8px 0;border-color:'+(i<op.step?'#9bd9bd':i===op.step?'#9eb3ff':'var(--line)')+'"><b>'+(i+1)+'. '+esc(s)+'</b><span class="pill" style="float:right">'+(i<op.step?'Concluída':i===op.step?'Atual':'A iniciar')+'</span></div>').join('');document.querySelector('#opHistory').innerHTML='<h3>Histórico</h3>'+op.history.map(x=>'<p class="muted">'+esc(x)+'</p>').join('')};document.querySelector('#opNext').onclick=()=>{if(op.step<stages.length){op.history.unshift('Concluída: '+stages[op.step]+' · '+new Date().toLocaleString('pt-BR'));op.step++;saveOp();renderOp()}};document.querySelector('#opBack').onclick=()=>{if(op.step>0){op.step--;op.history.unshift('Reaberta: '+stages[op.step]+' · '+new Date().toLocaleString('pt-BR'));saveOp();renderOp()}};document.querySelector('[data-view="manualOperation"]').onclick=()=>{document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id==='manualOperation'));document.querySelectorAll('.nav').forEach(v=>v.classList.toggle('active',v.dataset.view==='manualOperation'));document.querySelector('#title').textContent='Central de operação';document.querySelector('#subtitle').textContent='Avanço, retorno e histórico do fluxo manual.';renderOp()};renderOp()}
  const oldExport=document.querySelector('#export')?.onclick;document.querySelector('#export')?.addEventListener('click',()=>{const payload={exportedAt:new Date().toISOString(),sites,links,content,campaigns,events,operation:read('traficcagent-mvd-operation-v1',{})};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.download='traficcagent-mvd-export.json';a.click()});
  ensureOperationView();ensureCampaignView();document.querySelector('#campaignSearch')?.addEventListener('input',renderCampaigns);renderAll();window.mvdManual={sites,links,content,campaigns,events,save};
})();
